import{_ as l,a0 as o,w as d,s as r,ao as t,I as p,x as n,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何把 awk 脚本移植到 Python | LCTT x X-CMD","titleTemplate":false,"description":"如何把 awk 脚本移植到 Python | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何把 awk 脚本移植到 Python | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何把 awk 脚本移植到 Python | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191115 How to port an awk script to Python","title":"如何把 awk 脚本移植到 Python","tag":"201912","desc":""},"relativePath":"201912/20191115 How to port an awk script to Python.md","filePath":"[post].md"}'),h={name:"201912/20191115 How to port an awk script to Python.md"};function k(c,s,f,g,u,y){const a=o("Link");return d(),r("div",null,[s[21]||(s[21]=t(`<h1 id="如何把-awk-脚本移植到-python" tabindex="-1">如何把 awk 脚本移植到 Python <a class="header-anchor" href="#如何把-awk-脚本移植到-python" aria-label="Permalink to “如何把 awk 脚本移植到 Python”">​</a></h1><blockquote><p>将一个 awk 脚本移植到 Python 主要在于代码风格而不是转译。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201912/08/095256ko6xdfwooe8zctfz.jpg" alt=""></p><p>脚本是解决问题的有效方法，而 awk 是编写脚本的出色语言。它特别擅长于简单的文本处理，它可以带你完成配置文件的某些复杂重写或目录中文件名的重新格式化。</p><h3 id="何时从-awk-转向-python" tabindex="-1">何时从 awk 转向 Python <a class="header-anchor" href="#何时从-awk-转向-python" aria-label="Permalink to “何时从 awk 转向 Python”">​</a></h3><p>但是在某些方面，awk 的限制开始显现出来。它没有将文件分解为模块的真正概念，它缺乏质量错误报告，并且缺少了现在被认为是编程语言工作原理的其他内容。当编程语言的这些丰富功能有助于维护关键脚本时，移植将是一个不错的选择。</p><p>我最喜欢的完美移植 awk 的现代编程语言是 Python。</p><p>在将 awk 脚本移植到 Python 之前，通常值得考虑一下其原始使用场景。例如，由于 awk 的局限性，通常从 Bash 脚本调用 awk 代码，其中包括一些对 <code>sed</code>、<code>sort</code> 之类的其它命令行常见工具的调用。 最好将所有内容转换为一个一致的 Python 程序。有时，脚本会做出过于宽泛的假设，例如，即使实际上只运行一个文件，该代码也可能允许任意数量的文件。</p><p>在仔细考虑了上下文并确定了要用 Python 替代的东西之后，该编写代码了。</p><h3 id="标准-awk-到-python-功能" tabindex="-1">标准 awk 到 Python 功能 <a class="header-anchor" href="#标准-awk-到-python-功能" aria-label="Permalink to “标准 awk 到 Python 功能”">​</a></h3><p>以下 Python 功能是有用的，需要记住：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(some_file_name) as fpin:</span></span>
<span class="line"><span>    for line in fpin:</span></span>
<span class="line"><span>        pass # do something with line</span></span></code></pre></div><p>此代码将逐行循环遍历文件并处理这些行。</p><p>如果要访问行号（相当于 awk 的 <code>NR</code>），则可以使用以下代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(some_file_name) as fpin:</span></span>
<span class="line"><span>    for nr, line in enumerate(fpin):</span></span>
<span class="line"><span>        pass # do something with line</span></span></code></pre></div><h3 id="在-python-中实现多文件的-awk-式行为" tabindex="-1">在 Python 中实现多文件的 awk 式行为 <a class="header-anchor" href="#在-python-中实现多文件的-awk-式行为" aria-label="Permalink to “在 Python 中实现多文件的 awk 式行为”">​</a></h3><p>如果你需要能够遍历任意数量的文件同时保持行数的持续计数（类似 awk 的 <code>FNR</code>），则此循环可以做到这一点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def awk_like_lines(list_of_file_names):</span></span>
<span class="line"><span>    def _all_lines():</span></span>
<span class="line"><span>        for filename in list_of_file_names:</span></span>
<span class="line"><span>            with open(filename) as fpin:</span></span>
<span class="line"><span>                yield from fpin</span></span>
<span class="line"><span>    yield from enumerate(_all_lines())</span></span></code></pre></div><p>此语法使用 Python 的<em>生成器</em>和 <code>yield from</code> 来构建<em>迭代器</em>，该迭代器将遍历所有行并保持一个持久计数。</p><p>如果你需要同时使用 <code>FNR</code> 和 <code>NR</code>，这是一个更复杂的循环：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def awk_like_lines(list_of_file_names):</span></span>
<span class="line"><span>    def _all_lines():</span></span>
<span class="line"><span>        for filename in list_of_file_names:</span></span>
<span class="line"><span>            with open(filename) as fpin:</span></span>
<span class="line"><span>                yield from enumerate(fpin)</span></span>
<span class="line"><span>    for nr, (fnr, line) in _all_lines:</span></span>
<span class="line"><span>        yield nr, fnr, line</span></span></code></pre></div><h3 id="更复杂的-fnr、nr-和行数的-awk-行为" tabindex="-1">更复杂的 FNR、NR 和行数的 awk 行为 <a class="header-anchor" href="#更复杂的-fnr、nr-和行数的-awk-行为" aria-label="Permalink to “更复杂的 FNR、NR 和行数的 awk 行为”">​</a></h3><p>如果 <code>FNR</code>、<code>NR</code> 和行数这三个你全都需要，仍然会有一些问题。如果确实如此，则使用三元组（其中两个项目是数字）会导致混淆。命名参数可使该代码更易于阅读，因此最好使用 <code>dataclass</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import dataclass</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@dataclass.dataclass(frozen=True)</span></span>
<span class="line"><span>class AwkLikeLine:</span></span>
<span class="line"><span>    content: str</span></span>
<span class="line"><span>    fnr: int</span></span>
<span class="line"><span>    nr: int</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def awk_like_lines(list_of_file_names):</span></span>
<span class="line"><span>    def _all_lines():</span></span>
<span class="line"><span>        for filename in list_of_file_names:</span></span>
<span class="line"><span>            with open(filename) as fpin:</span></span>
<span class="line"><span>                yield from enumerate(fpin)</span></span>
<span class="line"><span>    for nr, (fnr, line) in _all_lines:</span></span>
<span class="line"><span>        yield AwkLikeLine(nr=nr, fnr=fnr, line=line)</span></span></code></pre></div><p>你可能想知道，为什么不一直用这种方法呢？使用其它方式的的原因是总用这种方法太复杂了。如果你的目标是把一个通用库更容易地从 awk 移植到 Python，请考虑这样做。但是编写一个可以使你确切地了解特定情况所需的循环的方法通常更容易实现，也更容易理解（因而易于维护）。</p><h3 id="理解-awk-字段" tabindex="-1">理解 awk 字段 <a class="header-anchor" href="#理解-awk-字段" aria-label="Permalink to “理解 awk 字段”">​</a></h3><p>一旦有了与一行相对应的字符串，如果要转换 awk 程序，则通常需要将其分解为<em>字段</em>。Python 有几种方法可以做到这一点。这将把行按任意数量的连续空格拆分，返回一个字符串列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line.split()</span></span></code></pre></div><p>如果需要另一个字段分隔符，比如以 <code>:</code> 分隔行，则需要 <code>rstrip</code> 方法来删除最后一个换行符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line.rstrip(&quot;\\n&quot;).split(&quot;:&quot;)</span></span></code></pre></div><p>完成以下操作后，列表 <code>parts</code> 将存有分解的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>parts = line.rstrip(&quot;\\n&quot;).split(&quot;:&quot;)</span></span></code></pre></div>`,32)),p("p",null,[s[1]||(s[1]=n("这种拆分非常适合用来处理参数，但是我们处于",-1)),i(a,{href:"https://en.wikipedia.org/wiki/Off-by-one_error"},{default:e(()=>[...s[0]||(s[0]=[n("偏差一个的错误",-1)])]),_:1}),s[2]||(s[2]=t("场景中。现在 <code>parts[0]</code> 将对应于 awk 的 <code>$1</code>，<code>parts[1]</code> 将对应于 awk 的 <code>$2</code>，依此类推。之所以偏差一个，是因为 awk 计数“字段”从 1 开始，而 Python 从 0 开始计数。在 awk 中，<code>$0</code> 是整个行 —— 等同于 <code>line.rstrip(&quot;\\n&quot;)</code>，而 awk 的 <code>NF</code>（字段数）更容易以 <code>len(parts)</code> 的形式得到。",17))]),s[22]||(s[22]=p("h3",{id:"移植-awk-字段到-python",tabindex:"-1"},[n("移植 awk 字段到 Python "),p("a",{class:"header-anchor",href:"#移植-awk-字段到-python","aria-label":"Permalink to “移植 awk 字段到 Python”"},"​")],-1)),p("p",null,[s[4]||(s[4]=n("例如，让我们将这个单行代码“",-1)),i(a,{href:"https://opensource.com/article/19/10/remove-duplicate-lines-files-awk"},{default:e(()=>[...s[3]||(s[3]=[n("如何使用 awk 从文件中删除重复行",-1)])]),_:1}),s[5]||(s[5]=n("”转换为 Python。",-1))]),s[23]||(s[23]=t(`<p><code>awk</code> 中的原始代码是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39;!visited[$0]++&#39; your_file &gt; deduplicated_file</span></span></code></pre></div><p>“真实的” Python 转换将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import collections</span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>visited = collections.defaultdict(int)</span></span>
<span class="line"><span>for line in open(&quot;your_file&quot;):</span></span>
<span class="line"><span>    did_visit = visited[line]</span></span>
<span class="line"><span>    visited[line] += 1</span></span>
<span class="line"><span>    if not did_visit:</span></span>
<span class="line"><span>        sys.stdout.write(line)</span></span></code></pre></div><p>但是，Python 比 awk 具有更多的数据结构。与其计数访问次数（除了知道是否看到一行，我们不使用它），为什么不记录访问的行呢？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>visited = set()</span></span>
<span class="line"><span>for line in open(&quot;your_file&quot;):</span></span>
<span class="line"><span>    if line in visited:</span></span>
<span class="line"><span>        continue</span></span>
<span class="line"><span>    visited.add(line)</span></span>
<span class="line"><span>    sys.stdout.write(line)</span></span></code></pre></div><h3 id="编写-python-化的-awk-代码" tabindex="-1">编写 Python 化的 awk 代码 <a class="header-anchor" href="#编写-python-化的-awk-代码" aria-label="Permalink to “编写 Python 化的 awk 代码”">​</a></h3><p>Python 社区提倡编写 Python 化的代码，这意味着它要遵循公认的代码风格。更加 Python 化的方法将区分<em>唯一性</em>和输入/输出的关注点。此更改将使对代码进行单元测试更加容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def unique_generator(things):</span></span>
<span class="line"><span>    visited = set()</span></span>
<span class="line"><span>    for thing in things:</span></span>
<span class="line"><span>        if thing in visited:</span></span>
<span class="line"><span>            continue</span></span>
<span class="line"><span>        visited.add(things)</span></span>
<span class="line"><span>        yield thing</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import sys</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>for line in unique_generator(open(&quot;your_file&quot;)):</span></span>
<span class="line"><span>    sys.stdout.write(line)</span></span></code></pre></div><p>将所有逻辑置于输入/输出代码之外，可以更好地分离问题，并提高代码的可用性和可测试性。</p><h3 id="结论-python-可能是一个不错的选择" tabindex="-1">结论：Python 可能是一个不错的选择 <a class="header-anchor" href="#结论-python-可能是一个不错的选择" aria-label="Permalink to “结论：Python 可能是一个不错的选择”">​</a></h3><p>将 awk 脚本移植到 Python 时，通常是在考虑适当的 Python 代码风格时重新实现核心需求，而不是按条件/操作进行笨拙的音译。考虑原始上下文并产生高质量的 Python 解决方案。虽然有时候使用 awk 的 Bash 单行代码可以完成这项工作，但 Python 编码是通往更易于维护的代码的途径。</p><p>另外，如果你正在编写 awk 脚本，我相信您也可以学习 Python！如果你有任何疑问，请告诉我。</p><hr>`,14)),p("p",null,[s[7]||(s[7]=n("via: ",-1)),i(a,{href:"https://opensource.com/article/19/11/awk-to-python"},{default:e(()=>[...s[6]||(s[6]=[n("https://opensource.com/article/19/11/awk-to-python",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("作者：",-1)),i(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[8]||(s[8]=[n("Moshe Zadka",-1)])]),_:1}),s[13]||(s[13]=n(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[9]||(s[9]=[n("lujun9972",-1)])]),_:1}),s[14]||(s[14]=n(" 译者：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1}),s[15]||(s[15]=n(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[18]||(s[18]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[16]||(s[16]=[n("LCTT",-1)])]),_:1}),s[19]||(s[19]=n(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[17]||(s[17]=[n("Linux中国",-1)])]),_:1}),s[20]||(s[20]=n(" 荣誉推出",-1))])])}const _=l(h,[["render",k]]);export{m as __pageData,_ as default};
